function parseJsonFromString(value) {
  if (!value || typeof value !== 'string') return null;

  const cleaned = value
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (_) {}
    }
  }

  return null;
}

function readAiPayload(input) {
  // n8n sometimes sends the OpenAI node output as an array
  const itemJson = Array.isArray(input) ? input[0] : input;

  // OpenAI Responses / Analyze format:
  // content: [{ type: "output_text", text: "{...}" }]
  if (Array.isArray(itemJson?.content)) {
    const textBlock = itemJson.content.find(
      (block) => block.type === 'output_text' && block.text
    );

    if (textBlock?.text) {
      const parsed = parseJsonFromString(textBlock.text);
      if (parsed) return parsed;
    }
  }

  // Other possible formats
  const candidates = [
    itemJson?.output,
    itemJson?.text,
    itemJson?.message?.content,
    itemJson?.choices?.[0]?.message?.content,
    itemJson?.data,
  ];

  for (const candidate of candidates) {
    if (!candidate) continue;

    if (typeof candidate === 'object' && !Array.isArray(candidate)) {
      return candidate;
    }

    if (typeof candidate === 'string') {
      const parsed = parseJsonFromString(candidate);
      if (parsed) return parsed;
    }
  }

  return {};
}

function uuid(prefix) {
  const random = Math.random().toString(36).slice(2, 10);
  return `${prefix}_${Date.now()}_${random}`;
}

function parseDateFlexible(dateValue) {
  if (!dateValue) return null;

  if (dateValue instanceof Date && !Number.isNaN(dateValue.getTime())) {
    return dateValue;
  }

  const raw = String(dateValue).trim();

  // Handles DD-MM-YYYY or DD/MM/YYYY
  const dmyMatch = raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);
  if (dmyMatch) {
    const day = Number(dmyMatch[1]);
    const month = Number(dmyMatch[2]) - 1;
    const year = Number(dmyMatch[3]);
    const parsed = new Date(Date.UTC(year, month, day));

    if (!Number.isNaN(parsed.getTime())) return parsed;
  }

  // Handles YYYY-MM-DD
  const ymdMatch = raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
  if (ymdMatch) {
    const year = Number(ymdMatch[1]);
    const month = Number(ymdMatch[2]) - 1;
    const day = Number(ymdMatch[3]);
    const parsed = new Date(Date.UTC(year, month, day));

    if (!Number.isNaN(parsed.getTime())) return parsed;
  }

  const parsed = new Date(raw);
  if (!Number.isNaN(parsed.getTime())) return parsed;

  return null;
}

function formatDateDDMMYYYY(date) {
  if (!date || Number.isNaN(date.getTime())) return null;

  const day = String(date.getUTCDate()).padStart(2, '0');
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const year = date.getUTCFullYear();

  return `${day}-${month}-${year}`;
}

function calculateWarrantyExpiry(purchaseDate, warrantyMonths) {
  const purchase = parseDateFlexible(purchaseDate);
  const months = Number(warrantyMonths);

  if (!purchase || !months || Number.isNaN(months)) return null;

  const expiry = new Date(purchase);
  expiry.setUTCMonth(expiry.getUTCMonth() + months);

  // Expiry should usually be one day before exact month completion
  expiry.setUTCDate(expiry.getUTCDate() - 1);

  return formatDateDDMMYYYY(expiry);
}

function warrantyStatus(expiryDate) {
  const expiry = parseDateFlexible(expiryDate);
  if (!expiry) return 'Unknown';

  const today = new Date();
  const todayUtc = new Date(Date.UTC(
    today.getUTCFullYear(),
    today.getUTCMonth(),
    today.getUTCDate()
  ));

  const inThirtyDays = new Date(todayUtc);
  inThirtyDays.setUTCDate(inThirtyDays.getUTCDate() + 30);

  if (expiry < todayUtc) return 'Expired';
  if (expiry <= inThirtyDays) return 'Expiring Soon';
  return 'Active';
}

// Source node
const source = $node['When Executed by Router'].json;

// Correct actual Google Drive upload node name
const drive = $node['Upload file'].json;

// AI output
const ai = readAiPayload($json);

// Dates and IDs
const now = new Date().toISOString();
const uploadDate = now.slice(0, 10);
const documentId = uuid('doc');
const productId = uuid('prod');

// If warranty expiry is missing but purchase date + warranty months are available, calculate it
const calculatedWarrantyExpiry = calculateWarrantyExpiry(
  ai.purchase_date,
  ai.warranty_period_months
);

const finalWarrantyExpiryDate =
  ai.warranty_expiry_date || calculatedWarrantyExpiry || null;

const status = warrantyStatus(finalWarrantyExpiryDate);

const driveLink =
  drive.webViewLink ||
  drive.webContentLink ||
  drive.webUrl ||
  drive.alternateLink ||
  drive.url ||
  (drive.id ? `https://drive.google.com/file/d/${drive.id}/view` : '');

return [
  {
    json: {
      document_id: documentId,
      product_id: productId,

      user_id: String(source.telegram_user_id || ''),
      chat_id: source.chat_id,
      telegram_user_id: source.telegram_user_id,
      user_name: source.user_name,

      telegram_file_id: source.file_id,
      file_name: source.file_name,
      file_type: source.file_type,
      mime_type: source.mime_type,
      message_text: source.message_text,

      google_drive_link: driveLink,
      google_drive_file_id: drive.id || drive.fileId || '',

      document_type: ai.document_type || ai.document_category || 'unknown',
      product_name: ai.product_name || null,
      brand: ai.brand || null,
      category: ai.category || ai.product_category || 'unknown',
      seller: ai.seller || ai.seller_name || null,
      invoice_number: ai.invoice_number || null,
      purchase_date: ai.purchase_date || null,
      purchase_amount: ai.purchase_amount || ai.purchase_price || null,

      warranty_period_months: ai.warranty_period_months || null,
      warranty_expiry_date: finalWarrantyExpiryDate,

      return_window_days: ai.return_window_days || null,
      return_expiry_date: ai.return_expiry_date || null,

      support_email_found_in_document:
        ai.support_email_found_in_document ||
        ai.manufacturer_or_seller_email ||
        null,

      support_phone_found_in_document:
        ai.support_phone_found_in_document || null,

      confidence_score: ai.confidence_score ?? ai.confidence ?? null,

      missing_fields: Array.isArray(ai.missing_fields)
        ? ai.missing_fields.join(', ')
        : (ai.missing_fields || ''),

      ocr_text: ai.ocr_text || '',
      processing_status: 'Processed',
      upload_date: uploadDate,
      created_at: now,
      last_updated: now,
      warranty_status: status,

      notes: calculatedWarrantyExpiry && !ai.warranty_expiry_date
        ? `Warranty expiry calculated from purchase_date and warranty_period_months.`
        : ''
    }
  }
];

